:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-footer: #0f3460;
  --accent-red: #e94560;
  --accent-gold: #f5a623;
  --accent-cream: #fdf6ec;
  --text-primary: #fdf6ec;
  --text-muted: #a8b2c8;
  --disc-dark: #111118;
  --disc-groove: #2a2a3e;
  --disc-label: #e94560;
  --tag-bg: #0f3460;
  --tag-border: #e94560;
  --btn-bg: #e94560;
  --btn-text: #fdf6ec;
  --divider-color: #2a3a5e;
  --status-bg: #1b4d2e;
  --status-text: #4ade80;
}

.record-card {
  background: var(--bg-card);
  border-radius: 16px;
  width: 460px;
  overflow: hidden;
  border: 1px solid var(--divider-color);
}

.card-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid var(--divider-color);
}

.store-badge {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.5px;
}

.status {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 20px;
}

.status.open {
  background: var(--status-bg);
  color: var(--status-text);
}

.store-info {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 20px 20px 16px;
}

.record-disc {
  flex-shrink: 0;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: var(--disc-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border: 3px solid var(--disc-groove);
  margin: 0;
}

.disc-inner {
  position: absolute;
  width: 82px;
  height: 82px;
  border-radius: 50%;
  border: 2px solid var(--disc-groove);
}

.disc-label {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--disc-label);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.label-text {
  font-size: 7px;
  font-weight: 900;
  color: var(--accent-cream);
  letter-spacing: 1px;
}

.store-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.store-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.store-address {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
}

.store-hours {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
}

.genre-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-red);
  background: var(--tag-bg);
  border: 1px solid var(--tag-border);
  border-radius: 4px;
  padding: 2px 8px;
}

.card-footer {
  background: var(--bg-footer);
  display: flex;
  align-items: center;
  padding: 12px 16px;
  gap: 0;
  border-top: 1px solid var(--divider-color);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  flex: 1;
}

.stat-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-gold);
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.divider {
  width: 1px;
  height: 32px;
  background: var(--divider-color);
  flex-shrink: 0;
}

.visit-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  margin-left: 12px;
  flex-shrink: 0;
}
